import CryptoKit
import Foundation
import MeetingBuddyApplication
import MeetingBuddyDomain

public actor UnavailableLocalTranscriptionProvider:
    TranscriptionProvider
{
    public nonisolated let metadata =
        try! ProviderMetadata(
            providerIdentifier: "apple-speech",
            modelIdentifier:
                "speech-analyzer-transcriber",
            clientVersion:
                "blueminutes-unavailable-local-speech-v1"
        )
    public nonisolated let route:
        ModelExecutionRoute = .appleOnDevice

    public init() {}

    public func isModelInstalled(
        for language: LanguageTag
    ) -> Bool {
        false
    }

    public func transcribe(
        _ request: TranscriptionRequest
    ) throws -> TranscriptionChunkResult {
        throw AIProviderContractError
            .modelUnavailable(
                "Apple on-device speech is unavailable on this macOS version."
            )
    }
}

/// A fixed, synthetic, non-sensitive voice sample saying
/// "Blue Minutes test." It contains no user or meeting audio.
enum BundledSTTConnectionSample {
    static let expectedNormalizedTranscript =
        "blueminutestest"

    @inline(never)
    static func wavData() throws -> Data {
        guard let data = Data(
            base64Encoded: encodedWAV,
            options: .ignoreUnknownCharacters
        ),
            data.count == 23_276,
            SHA256.hash(data: data).map({
                String(format: "%02x", $0)
            }).joined()
                == "2db74b9f486ddac1b3d88cda9f6552f4220ade03e52f36ca042485b291aac6d5"
        else {
            throw AIProviderContractError.invalidRequest(
                "The bundled non-sensitive STT sample failed integrity validation."
            )
        }
        return data
    }

    private static let encodedWAV = """

"""
}
